"""Build the source-color Dart/Outpost comparison and complete arena budget view."""
import argparse
import json
from pathlib import Path


def main():
    ap=argparse.ArgumentParser(description=__doc__);ap.add_argument('--out',type=Path,required=True);a=ap.parse_args();out=a.out.resolve();summary=json.loads((out/'summary.json').read_bytes());review=json.loads((out/'review.json').read_bytes());prior=json.loads((out.parent/'rmuc2027-arena-budget/summary.json').read_bytes());payload={'before':prior['groups'],'after':summary['groups'],'totals':summary['totals'],'prior_totals':summary['prior_totals'],'images':[{'id':r['id'],'kind':r['kind'],'triangles':r['triangles'],'paths':{v['view']:str(out/r['images']/(v['view']+'.webp')) for v in r['views']}} for r in review['entries']]}
    html='''<!doctype html><html><head><meta charset="utf-8"><style>
body{font-family:var(--font-sans,system-ui);color:var(--foreground,#222);margin:0}p{line-height:1.45;margin:0 0 12px}.muted,small{color:var(--muted-foreground,#666)}.stats{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:16px 0}.stats>div{border-top:2px solid var(--border,#ccc);padding-top:9px}.stats b{display:block;font-size:23px}.stats small{display:block;margin-top:4px}table{border-collapse:collapse;width:100%;font-size:13px;margin:12px 0 16px}th,td{text-align:right;border-bottom:1px solid var(--border,#ddd);padding:8px 3px}th:first-child,td:first-child{text-align:left}.bar{height:5px;margin-top:5px;border-radius:4px;background:var(--chart-1,#557cbd)}.note{font-size:13px}.controls{display:grid;grid-template-columns:3fr 1fr;gap:12px;margin:18px 0 10px}label{font-size:13px}select{display:block;max-width:100%;width:100%;margin-top:5px;padding:8px;color:inherit;background:var(--background,white);border:1px solid var(--border,#ccc);border-radius:5px;font:inherit}#labels{display:grid;grid-template-columns:1fr 1fr;text-align:center;font-size:13px;gap:6px;margin-bottom:6px}img{display:block;width:100%;height:auto;border-radius:6px}summary{cursor:pointer;margin:16px 0}.wrap{overflow-x:auto}@media(max-width:480px){.controls{grid-template-columns:1fr}.stats b{font-size:19px}table{font-size:12px}}
</style></head><body><p><b>Dart station and Outpost · next LOD candidate</b><br><span class="muted">Exact LED triangles and source materials · independent visual and contact meshes</span></p>
<div class="wrap"><table><thead><tr><th>Complete group, both sides</th><th>Visual before → after</th><th>Reduction</th><th>Collision budget before → after*</th></tr></thead><tbody id="groups"></tbody></table></div>
<div class="stats"><div><b id="visual"></b>whole-arena placed visual triangles<small id="visual-save"></small></div><div><b id="collision"></b>whole-arena collision planning budget*<small id="collision-save"></small></div></div>
<p class="note">Outpost rotor modules fall from ~19k to ~8k visual triangles each, with ~2.2k-triangle contact meshes. Dart’s door improves; its large frame remains the main Dart bottleneck. The pass keeps the earlier panel collider wherever it is cheaper, choosing independently per rigid member.</p>
<div class="controls"><label>Model / mesh<select id="part"></select></label><label>View<select id="view"><option>oblique</option><option>reverse</option><option>top</option><option>front</option><option>back</option><option>bottom</option><option>side</option></select></label></div><div id="labels"></div><img id="image" alt="Matched approved and reduced equipment views"><p class="note muted" id="kind"></p>
<p class="note muted">*Prospective collision accounting, not installed runtime physics. Seven samples per triangle in both directions and per material guard the LOD: 2 mm for visuals, 6 mm for contacts. A local source ring preserves the upper Outpost port’s projectile clearance. Twenty-one source-qualified opening paths remain clear in finite checks. Motion and scoring detectors remain separate.</p>
<details><summary>Whole-arena group breakdown and shared storage</summary><div class="wrap"><table><thead><tr><th>Group</th><th>Placed visuals</th><th>Collision budget*</th></tr></thead><tbody id="arena"></tbody></table></div><p class="note muted" id="storage"></p></details>
<script>const d=__DATA__,num=n=>n.toLocaleString(),by=Object.fromEntries(d.before.map(r=>[r.group,r]));for(const name of ['Dart station','Outpost']){const a=d.after.find(r=>r.group===name),b=by[name],tr=document.createElement('tr');for(const v of [name,`${num(b.visual_placed)} → ${num(a.visual_placed)}`,((1-a.visual_placed/b.visual_placed)*100).toFixed(1)+'%',`${num(b.collision_budget_placed)} → ${num(a.collision_budget_placed)}`]){const td=document.createElement('td');td.textContent=v;tr.append(td)}document.getElementById('groups').append(tr)}document.getElementById('visual').textContent=num(d.totals.visual_placed);document.getElementById('collision').textContent=num(d.totals.collision_budget_placed);document.getElementById('visual-save').textContent=num(d.prior_totals.visual_placed-d.totals.visual_placed)+' fewer · '+((1-d.totals.visual_placed/d.prior_totals.visual_placed)*100).toFixed(1)+'%';document.getElementById('collision-save').textContent=num(d.prior_totals.collision_budget_placed-d.totals.collision_budget_placed)+' fewer · '+((1-d.totals.collision_budget_placed/d.prior_totals.collision_budget_placed)*100).toFixed(1)+'%';for(const r of d.after){const tr=document.createElement('tr');for(const v of [r.group,num(r.visual_placed),num(r.collision_budget_placed)]){const td=document.createElement('td');td.textContent=v;tr.append(td)}document.getElementById('arena').append(tr)}document.getElementById('storage').textContent=`${num(d.totals.stored_triangles)} stored mesh triangles, shared across all 171 placements and 116 definitions. No unreferenced mesh triangles. Runtime assets unchanged.`;const part=document.getElementById('part'),view=document.getElementById('view');d.images.forEach((r,i)=>part.add(new Option(r.id,i)));part.value=1;function show(){const r=d.images[+part.value];document.getElementById('image').src=r.paths[view.value];document.getElementById('labels').replaceChildren(...['reference','candidate'].map(s=>{const e=document.createElement('span');e.textContent=(s==='reference'?'Approved reference':'New candidate')+' · '+num(r.triangles[s])+' tris';return e}));document.getElementById('kind').textContent=r.kind==='collision'?'Collision only · diagnostic blue, separate from the source-colored visual model.':'Source-colored visual model · matched native pose and framing; two-sided diagnostic rendering.'}part.onchange=view.onchange=show;show();</script></body></html>'''
    (out/'review.html').write_text(html.replace('__DATA__',json.dumps(payload)));print(out/'review.html')


if __name__=='__main__':main()
